#!/usr/bin/env php
<?php
$count = trim(fgets(STDIN));

$line = trim(fgets(STDIN));
$array = array_map('intval', explode(' ', $line));

for(;;) {
	rsort($array);
	if ($array[0] !== $array[$count - 1] && $array[1] !== 0) {
		$sub = $array[1];
		for ($i = 1; $i < $count; $i++) {
			if ($array[$i] !== $array[0]) {
				$sub = $array[$i];
				break;
			}
		}
		$array[0] = $array[0] - $sub;
	} else {
		echo array_sum($array);exit();
	}
}
